    h, w = len(grid), len(grid[0])
    sep_rows = [r for r in range(h) if all(v == 8 for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]

    def regions(n, separators):
        result, start = [], 0
        for s in separators:
            if start < s:
                result.append((start, s))
            start = s + 1
        if start < n:
            result.append((start, n))
        return result

    rr, cc = regions(h, sep_rows), regions(w, sep_cols)
    locs = {2: [], 3: []}
    for ri, (a, b) in enumerate(rr):
        for ci, (x, y) in enumerate(cc):
            found = {grid[r][c] for r in range(a, b) for c in range(x, y) if grid[r][c] in (2, 3)}
            for color in found:
                locs[color].append((ri, ci))

    painted = {}
    for color, points in locs.items():
        for i, (r1, c1) in enumerate(points):
            for r2, c2 in points[i + 1:]:
                if r1 == r2:
                    for c in range(min(c1, c2), max(c1, c2) + 1):
                        painted[(r1, c)] = painted.get((r1, c), 0) | (1 if color == 2 else 2)
                elif c1 == c2:
                    for r in range(min(r1, r2), max(r1, r2) + 1):
                        painted[(r, c1)] = painted.get((r, c1), 0) | (1 if color == 2 else 2)

    out = [row[:] for row in grid]
    for (ri, ci), mask in painted.items():
        color = 6 if mask == 3 else 2 if mask == 1 else 3
        a, b = rr[ri]
